/**
 * Dataset reference detection.
 *
 * Questions cite datasets by filename ("the data frame in scooby.csv"). We
 * record just those filenames on each capture (`datasetRefs`); the actual CSV
 * content is NOT inlined into the export — it lives in datasets/<name>.csv
 * (generated by scripts/convert-rdata.mjs) and is pulled in by
 * scripts/import-captures.ts only when building the runnable eval fixtures.
 */

/** Filenames a question references, e.g. ["scooby.csv"]. Deduped, case kept. */
export function detectDatasetRefs(text: string): string[] {
  const out = new Set<string>();
  for (const m of text.matchAll(/\b([A-Za-z0-9_.\-]+\.csv)\b/g)) out.add(m[1]!);
  return [...out];
}
